Step 1 - Understand the problem
Write a C program that counts the vowels in a string entered by the user.

Step 2 - Plan the solution
1. Read a line with fgets (safer than gets).
2. Loop until the null terminator.
3. Convert each character to lowercase and compare it with a, e, i, o, u.

Step 3 - Write the code
#include <stdio.h>
#include <ctype.h>

int main(void) {
    char text[200];
    int count = 0;

    printf("Enter a string: ");
    fgets(text, sizeof(text), stdin);

    for (int i = 0; text[i] != '\0'; i++) {
        char c = tolower((unsigned char)text[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            count++;
        }
    }

    printf("Vowels: %d\n", count);
    return 0;
}

